files.content:
* {
  box-sizing: border-box;
}

html {
  min-height: 100%;
}

body {
  box-sizing: border-box;
  min-width: 850px;
  min-height: 100%;
  margin: 0;
  padding: 25px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #000;
}

a:hover {
  color: #fd24af;
}

.page {

  display: flex;
  justify-content: center;
  align-items: center;
  height: 100%;
  margin: 50px;
  padding: 25px;
  background-color: #5f0dee;
  position: relative;
}

.card {
  /* position: relative; */
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: center;
  width: 450px;
  height: 450px;
  border: 3px solid #fd24af;
  padding: 15px;
  color: white;
}

.card-title {
  font-weight: 800;
  font-size: 38px;
  text-transform: uppercase;
}

.card-img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.card-link {
  color: currentColor;
}
